#[cfg(test)]
mod new_order_req_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_new_order_req_codec() {
        let original = NewOrderReq {
            req_id: 123456789,
            channel_id: 1234,
            adapter: 42,
            account: "a".repeat(16),
            account_group: "a".repeat(16),
            cl_ord_id: "a".repeat(16),
            security_id: "a".repeat(12),
            market: 42,
            side: 42,
            price: -123456789,
            order_qty: -123456789,
            ord_type: 42,
            time_in_force: 42,
            pbu: "a".repeat(8),
            transact_time: 123456789,
            ts_recv_ns: 123456789,
            raw_ref: 123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(NewOrderReqRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        NewOrderReq::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = NewOrderReq::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

